  min-width: max-content;
  padding-right: 18px;
  border-left: 2px solid transparent;
}
.local-skill-code-line-number {
  width: 48px;
  padding-right: 14px;
  flex-shrink: 0;
  text-align: right;
  color: #727272;
  -webkit-user-select: none;
  -moz-user-select: none;
  user-select: none;
}
.local-skill-code-line-sign {
  width: 18px;
  flex-shrink: 0;
  -webkit-user-select: none;
  -moz-user-select: none;
  user-select: none;
  opacity: .8;
}
.local-skill-code-line code {
  font: inherit;
  white-space: inherit;
  background: none;
  padding: 0;
}
.local-skill-code-line.is-added {
  background: #2ea0431f;
  border-left-color: #3fb950;
}
.local-skill-code-line.is-removed {
  background: #f8514924;
  border-left-color: #f85149;
}
.local-skill-code-line.is-added .local-skill-code-line-sign {
  color: #6acb85;
}
.local-skill-code-line.is-removed .local-skill-code-line-sign {
