}
.local-skill-code-view.is-wrapped .local-skill-code-line {
  min-width: 0;
}
.local-skill-code-view.is-wrapped code {
  min-width: 0;
  overflow-wrap: anywhere;
}
.local-skill-code-view.is-compact {
  max-height: 250px;
}
.local-code-token-comment {
  color: #81888f;
}
.local-code-token-string {
  color: #a5d6a7;
}
.local-code-token-keyword {
  color: #c6a0f6;
}
.local-code-token-number {
  color: #e5bf8d;
}
.local-code-token-tag {
  color: #8ac7e9;
}
