@keyframes sketch-assets-modal-in {
  0% {
    opacity: 0;
    transform: scale(.98);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes sketch-assets-fade-in {
  0% {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.sketch-assets-overlay {
  background: #0a0c106b;
  animation: sketch-assets-fade-in .14s ease;
}
.sketch-assets-modal {
  --sketch-assets-r: 24px;
  position: relative;
  display: flex;
  flex-direction: column;
  width: 92vw;
  max-width: 1240px;
  height: 86vh;
  border-radius: var(--sketch-assets-r);
  background: #fffefaf5;
  border: 1px solid rgba(40,40,40,.12);
  box-shadow: 0 18px 44px #00000014;
  overflow: hidden;
  animation: sketch-assets-modal-in .16s ease;
}
.sketch-assets-modal.sketch-assets-lib {
  --lib-bg: #f4f4f5;
  --lib-panel: #ececee;
  --lib-main: #fafafa;
  --lib-line: rgba(0, 0, 0, .08);
  --lib-text: rgba(24, 24, 27, .94);
  --lib-muted: rgba(113, 113, 122, .9);
  --lib-active: rgba(59, 90, 140, .16);
  --lib-active-text: rgba(36, 58, 96, .96);
  width: 96vw;
  max-width: 1560px;
  height: 92vh;
  border-radius: 12px;
  background: var(--lib-main);
  border: 1px solid var(--lib-line);
  box-shadow: none;
}
.sketch-assets-modal.sketch-assets-lib.sketch-assets-modal-dark {
  --lib-bg: #101014;
  --lib-panel: #16161a;
  --lib-main: #121214;
  --lib-line: rgba(255, 255, 255, .08);
  --lib-text: rgba(244, 244, 245, .94);
  --lib-muted: rgba(161, 161, 170, .88);
  --lib-active: rgba(90, 120, 180, .22);
  --lib-active-text: rgba(220, 230, 255, .96);
  background: var(--lib-main);
  border-color: var(--lib-line);
  box-shadow: none;
}
.sketch-assets-lib-topbar {
  display: flex;
  align-items: center;
  gap: .55rem;
  flex-shrink: 0;
  flex-wrap: wrap;
  padding: .45rem .65rem;
  border-bottom: 1px solid var(--lib-line);
  background: var(--lib-panel);
}
.sketch-assets-lib-search-top {
  width: 200px;
  flex-shrink: 0;
}
.sketch-assets-lib-type-counts {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
}
.sketch-assets-lib-count-chip {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
  height: 28px;
  padding: 0 .55rem;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  color: var(--lib-muted);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
}
.sketch-assets-lib-count-chip:hover {
  background: #0000000d;
}
.sketch-assets-lib-count-chip.active {
  background: #00000014;
  color: var(--lib-text);
}
.sketch-assets-modal-dark .sketch-assets-lib-count-chip:hover {
  background: #ffffff0d;
}
.sketch-assets-modal-dark .sketch-assets-lib-count-chip.active {
  background: #ffffff1a;
}
.sketch-assets-lib-topbar-mid {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  flex-wrap: wrap;
}
.sketch-assets-sort-group {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
}
.sketch-assets-lib .sketch-assets-sort-group .sketch-assets-sort {
  padding-right: .55rem;
}
.sketch-assets-sort-dir {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px;
  border-radius: 6px;
  border: 1px solid var(--lib-line);
  background: transparent;
}
.sketch-assets-sort-dir-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--lib-muted);
  cursor: pointer;
}
.sketch-assets-sort-dir-btn:hover {
  background: #0000000f;
  color: var(--lib-text);
}
.sketch-assets-sort-dir-btn.active {
  background: #0000001a;
  color: var(--lib-text);
}
.sketch-assets-modal-dark .sketch-assets-sort-dir-btn:hover {
  background: #ffffff0f;
}
.sketch-assets-modal-dark .sketch-assets-sort-dir-btn.active {
  background: #ffffff1f;
}
.sketch-assets-lib-select-mode {
  display: inline-flex;
  align-items: center;
  gap: .45rem;
  margin-left: auto;
  color: var(--lib-muted);
  font-size: 12px;
  cursor: pointer;
  -webkit-user-select: none;
  -moz-user-select: none;
  user-select: none;
}
.sketch-assets-lib-switch {
  position: relative;
  width: 34px;
  height: 18px;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: #78788059;
  cursor: pointer;
  transition: background .14s ease;
}
.sketch-assets-lib-switch.on {
  background: #3b82f6;
}
.sketch-assets-lib-switch-knob {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 14px;
  height: 14px;
  border-radius: 999px;
  background: #fff;
  box-shadow: 0 1px 2px #00000040;
  transition: transform .14s ease;
}
.sketch-assets-lib-switch.on .sketch-assets-lib-switch-knob {
  transform: translate(16px);
}
.sketch-assets-lib-topbar-right {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
  margin-left: auto;
  flex-wrap: wrap;
}
.sketch-assets-lib-empty-hint {
  padding: .45rem .5rem;
  font-size: 11px;
  color: var(--lib-muted);
}
.sketch-assets-lib-status-line {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  color: var(--lib-muted);
  font-size: 12px;
}
.sketch-assets-lib-status-sel {
  color: var(--lib-muted);
  font-size: 11px;
}
.sketch-assets-lib-status-send {
  display: inline-flex;
  align-items: center;
  gap: .25rem;
  height: 22px;
  padding: 0 .5rem;
  border: 1px solid var(--lib-line);
  border-radius: 999px;
  background: transparent;
  color: var(--lib-text);
  font-size: 11px;
  cursor: pointer;
}
.sketch-assets-lib-status-send:hover:not(:disabled) {
  background: #3b82f61f;
}
.sketch-assets-lib-status-send:disabled {
  opacity: .45;
  cursor: default;
}
.sketch-assets-lib-status-meta {
  font-size: 12px;
  color: var(--lib-muted);
  font-variant-numeric: tabular-nums;
}
.sketch-assets-lib-shell {
  display: flex;
  flex: 1;
  min-height: 0;
}
.sketch-assets-lib-sidebar {
  width: 220px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: .65rem;
  padding: .7rem .55rem .85rem;
  border-right: 1px solid var(--lib-line);
  background: var(--lib-panel);
  overflow: hidden;
}
.sketch-assets-modal-dark .sketch-assets-lib-sidebar {
  border-right-color: var(--lib-line);
  background: var(--lib-panel);
}
.sketch-assets-lib-search {
  display: flex;
  align-items: center;
  gap: .4rem;
  height: 32px;
  padding: 0 .55rem;
  border-radius: 6px;
  border: 1px solid var(--lib-line);
  background: #ffffff8c;
  color: var(--lib-muted);
  box-shadow: none;
}
.sketch-assets-modal-dark .sketch-assets-lib-search {
  border-color: var(--lib-line);
  background: #ffffff0a;
  color: var(--lib-muted);
}
.sketch-assets-lib-search input {
  flex: 1;
  min-width: 0;
  border: none;
  outline: none;
  background: transparent;
  font-size: 12px;
  color: var(--lib-text);
}
.sketch-assets-lib-search input::-moz-placeholder {
  color: var(--lib-muted);
}
.sketch-assets-lib-search input::placeholder {
  color: var(--lib-muted);
}
.sketch-assets-lib-section {
  display: flex;
  flex-direction: column;
  gap: .15rem;
  min-height: 0;
}
.sketch-assets-lib-section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: .25rem .4rem .3rem;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .02em;
  color: var(--lib-muted);
}
.sketch-assets-modal-dark .sketch-assets-lib-section-head {
  color: var(--lib-muted);
}
.sketch-assets-lib-nav {
  display: flex;
  flex-direction: column;
  gap: 1px;
  overflow-y: auto;
  min-height: 0;
  padding-right: 1px;
}
.sketch-assets-lib-nav-item {
  display: flex;
  align-items: center;
  gap: .4rem;
  width: 100%;
  min-height: 30px;
  padding: .25rem .45rem;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--lib-text);
  font-size: 12px;
  text-align: left;
  cursor: pointer;
  transition: background .1s ease,color .1s ease;
  box-shadow: none;
}
.sketch-assets-lib-nav-item:hover {
  background: #0000000a;
}
.sketch-assets-lib-nav-item.active {
  background: var(--lib-active);
  color: var(--lib-active-text);
  font-weight: 600;
}
.sketch-assets-modal-dark .sketch-assets-lib-nav-item {
  color: var(--lib-text);
}
.sketch-assets-modal-dark .sketch-assets-lib-nav-item:hover {
  background: #ffffff0d;
}
.sketch-assets-modal-dark .sketch-assets-lib-nav-item.active {
  background: var(--lib-active);
  color: var(--lib-active-text);
}
.sketch-assets-lib-nav-item .lib-nav-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sketch-assets-lib-nav-item .lib-nav-count {
  flex-shrink: 0;
  font-size: 11px;
  color: var(--lib-muted);
  font-variant-numeric: tabular-nums;
}
.sketch-assets-lib-nav-item.active .lib-nav-count {
  color: inherit;
  opacity: .75;
}
.sketch-assets-lib-nav-badge {
  flex-shrink: 0;
  padding: .05rem .3rem;
  border-radius: 4px;
  background: #22c55e2e;
  color: #22c55efa;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .03em;
}
.sketch-assets-lib-main {
  flex: 1;
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: var(--lib-main);
}
.sketch-assets-lib-toolbar {
  display: none;
}
.sketch-assets-lib .sketch-assets-filters {
  border: 1px solid var(--lib-line);
  background: transparent;
  border-radius: 6px;
  box-shadow: none;
  padding: 2px;
  gap: 2px;
}
.sketch-assets-lib .sketch-assets-filter-item {
  height: 28px;
  min-width: 32px;
  border-radius: 4px;
  box-shadow: none;
}
.sketch-assets-lib .sketch-assets-filter-item.active {
  background: #00000014;
  border-color: transparent;
  box-shadow: none;
}
.sketch-assets-modal-dark.sketch-assets-lib .sketch-assets-filter-item.active {
  background: #ffffff1a;
}
