}
.canvas-pin-dot-stack {
  position: relative;
  display: block;
  height: var(--pin-node-dot-size);
  flex-shrink: 0;
}
.canvas-pin-dot {
  position: absolute;
  right: 0;
  top: 0;
  width: var(--pin-node-dot-size);
  height: var(--pin-node-dot-size);
  border-radius: 50%;
  transition: none;
}
.canvas-pin-dot[data-pin-presence=exiting] {
  pointer-events: none;
}
.canvas-pin-dot-presence {
  display: block;
  transition: translate .2s cubic-bezier(.4,0,.2,1),opacity .2s cubic-bezier(.4,0,.2,1),scale .2s cubic-bezier(.4,0,.2,1);
}
.canvas-pin-dot-presence[data-pin-presence=exiting] {
  opacity: 0;
  scale: .5;
}
.canvas-pin-dot-presence[data-pin-presence=present],.canvas-pin-dot-presence[data-pin-presence=entering] {
  opacity: 1;
  scale: 1;
}
@starting-style {
