.canvas-pin-swatch {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: var(--pin-control-size);
  height: var(--pin-control-size);
  border: 0;
  border-radius: 8px;
  background: transparent;
  cursor: pointer;
  overflow: visible;
}
.canvas-pin-swatch:hover,.canvas-pin-swatch:active {
  background: transparent;
}
.canvas-pin-ring {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  margin: auto;
  width: var(--pin-ring-size);
  height: var(--pin-ring-size);
  border-radius: 50%;
  border: var(--pin-ring-width) solid transparent;
