  opacity: 1;
  transform: scale(1);
}
.canvas-pin-ring--active {
  opacity: 1;
}
.canvas-pin-selector[data-theme=dark] .canvas-pin-ring--active {
  border-color: #fff;
}
.canvas-pin-selector[data-theme=light] .canvas-pin-ring--active {
  border-color: #18181b;
}
.canvas-pin-swatch-dot {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  width: var(--pin-swatch-dot-size);
  height: var(--pin-swatch-dot-size);
  border-radius: 50%;
  pointer-events: none;
}
.canvas-pin-indicator {
  position: absolute;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  width: var(--pin-indicator-size);
  height: var(--pin-indicator-size);
  color: #000;
  pointer-events: none;
  opacity: 0;
  transition: opacity .15s;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  line-height: 1;
  font-weight: 600;
}
.canvas-pin-indicator--partial {
  z-index: 10;
  opacity: 1;
}
.canvas-pin-indicator--hover {
  z-index: 20;
}
.canvas-pin-swatch:hover .canvas-pin-indicator--partial,.canvas-pin-swatch:focus-visible .canvas-pin-indicator--partial {
  opacity: 0;
}
.canvas-pin-swatch:hover .canvas-pin-indicator--hover,.canvas-pin-swatch:focus-visible .canvas-pin-indicator--hover {
