.sg-loading {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  pointer-events: none;
  container: sg-loading / inline-size;
  background: radial-gradient(ellipse at 50% 38%,#ffffff04,transparent 70%),#161618;
}
.sg-loading-mark {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 6px;
  width: 48px;
  height: 40px;
  padding: 10px 12px;
  margin-bottom: 18px;
  border: 1px solid #c9c6be38;
  border-radius: 7px;
  background: #19191b;
}
.sg-loading-mark:before {
  content: "";
  position: absolute;
  top: -6px;
  right: 5px;
  bottom: 5px;
  left: -6px;
  z-index: -1;
  border: 1px solid #c9c6be16;
  border-radius: 7px;
  transform: rotate(-8deg);
}
.sg-loading-mark i {
  display: block;
  height: 1px;
  flex-shrink: 0;
  width: 100%;
  border-radius: 2px;
  background: #d2cfc6;
  transform-origin: left;
  opacity: .35;
  animation: sg-loading-ink 3.6s ease-in-out infinite both;
  animation-play-state: paused;
}
.sg-loading-mark i:nth-child(2) {
  width: 68%;
  animation-delay: .18s;
}
.sg-loading-mark i:nth-child(3) {
  width: 84%;
  animation-delay: .36s;
}
.sg-loading[data-active=true] .sg-loading-mark i {
  animation-play-state: running;
}
.sg-loading-caption {
  position: absolute;
  bottom: 20px;
  inset-inline: 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  color: #a6a5a9;
  font-size: 11px;
  line-height: 1.5;
  font-variant-numeric: tabular-nums;
}
.sg-loading-progress {
  display: block;
  width: 64px;
  height: 2px;
  overflow: hidden;
  border-radius: 2px;
  background: #ffffff0a;
}
.sg-loading-progress i {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: #c6c1b76b;
  transform-origin: left;
  transition: transform .6s ease;
}
@keyframes sg-loading-ink {
  0%,to {
    opacity: .22;
    transform: scaleX(.55);
  }
  45%,60% {
    opacity: .8;
    transform: scaleX(1);
  }
}
@container sg-loading (max-width: 220px) {
  .sg-loading-mark {
    width: 34px;
    height: 28px;
    padding: 7px 9px;
    gap: 4px;
    margin-bottom: 20px;
