.mood-pad {
  --mp-size: 220px;
  --mp-radius: 16px;
  --mp-bg: #1d1d1e;
  --mp-dot: #f4f4f6;
  --mp-ring: #f6f6f8;
  --mp-label: rgba(255,255,255,.38);
  position: relative;
  width: var(--mp-size);
  height: var(--mp-size);
  border-radius: var(--mp-radius);
  border: 1px solid rgba(255,255,255,.05);
  background: var(--mp-bg);
  box-shadow: none;
  -webkit-user-select: none;
  -moz-user-select: none;
  user-select: none;
  touch-action: none;
  cursor: pointer;
  outline: none;
}
.mood-pad:focus-visible {
  box-shadow: inset 0 0 0 1px #ffffff2e;
}
.mood-pad__axis {
  position: absolute;
  font-size: 11px;
  color: var(--mp-label);
  letter-spacing: .02em;
  pointer-events: none;
  line-height: 1;
}
.mood-pad__axis--top {
  left: 50%;
  top: 12px;
  transform: translate(-50%);
}
.mood-pad__axis--bottom {
  left: 50%;
  bottom: 12px;
  transform: translate(-50%);
}
.mood-pad__axis--left {
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
}
.mood-pad__axis--right {
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
}
.mood-pad__dot {
  position: absolute;
  border-radius: 50%;
  background: var(--mp-dot);
  pointer-events: none;
  will-change: transform,opacity;
}
.mood-pad__dot.is-origin {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px #ffffff8c;
}
.mood-pad__dot.is-tick {
  animation: mood-pad-tick .28s cubic-bezier(.22,1,.36,1);
}
.mood-pad__handle {
  position: absolute;
  width: 30px;
  height: 30px;
  margin: -15px 0 0 -15px;
  border-radius: 50%;
  background: transparent;
  border: 2px solid var(--mp-ring);
  box-shadow: none;
  cursor: grab;
  z-index: 2;
  pointer-events: none;
}
.mood-pad.is-dragging .mood-pad__handle,.mood-pad.is-coasting .mood-pad__handle {
  cursor: grabbing;
  border-width: 2.5px;
}
.mood-pad.is-disabled {
  opacity: .5;
  pointer-events: none;
}
.mood-pad.is-busy .mood-pad__handle {
  border-color: #f6f6f8b3;
}
.mood-pad--light {
  --mp-bg: #f4f4f5;
  --mp-dot: #18181b;
  --mp-ring: #18181b;
  --mp-label: rgba(24,24,27,.45);
  border-color: #00000014;
}
.mood-pad--light:focus-visible {
  box-shadow: inset 0 0 0 1px #00000029;
}
.mood-pad--light .mood-pad__dot.is-origin {
  box-shadow: inset 0 0 0 1.5px #18181b73;
}
.mood-pad--light.is-busy .mood-pad__handle {
  border-color: #18181b8c;
}
@keyframes mood-pad-tick {
  0% {
    transform: scale(.86);
  }
  55% {
    transform: scale(1.08);
  }
  to {
    transform: scale(1);
  }
}
