.iu-workspace {
  --iu-bg: var(--studio-bg, #101012);
  --iu-surface: var(--studio-surface, #171719);
  --iu-soft: var(--studio-surface-2, #232327);
  --iu-border: var(--studio-border, #ffffff12);
  --iu-text: var(--studio-text-1, #eeeef2);
  --iu-muted: var(--studio-text-3, #90909b);
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  background: var(--iu-bg);
  color: var(--iu-text);
  font-size: 12px;
  color-scheme: var(--studio-content-scheme, dark);
}
.iu-workspace * {
  box-sizing: border-box;
}
.iu-workspace :where(button,input,textarea) {
  font: inherit;
  color: inherit;
}
.iu-workspace button {
  cursor: pointer;
}
.iu-workspace button:disabled {
  opacity: .4;
  cursor: not-allowed;
}
.iu-workspace :where(button,input,textarea,summary):focus-visible {
  outline: 2px solid var(--iu-muted);
  outline-offset: 3px;
}
.iu-workspace :where(input:not([type=range]),textarea) {
  width: 100%;
  border: 1px solid var(--iu-border);
  border-radius: 9px;
  background: var(--iu-bg);
  padding: 10px 11px;
  outline-offset: 2px;
}
.iu-select {
  min-width: 0;
}
.iu-workspace .iu-select-button {
  width: 100%;
  border: 1px solid var(--iu-border);
  border-radius: 10px;
  background: var(--iu-bg);
  padding: 10px 11px;
  color: var(--iu-text);
  outline: none;
  box-shadow: none;
}
.iu-workspace .iu-select-button:hover:not(:disabled) {
  background: var(--iu-surface);
}
.iu-workspace .iu-select-button:focus-visible {
  outline: none;
  border-color: var(--iu-muted);
}
.iu-select-menu button:focus-visible {
  outline: none;
  box-shadow: inset 0 0 0 1px currentColor;
}
.iu-workspace textarea {
  resize: vertical;
  min-height: 80px;
  line-height: 1.7;
}
.iu-workspace input::-moz-placeholder,.iu-workspace textarea::-moz-placeholder {
  color: var(--iu-muted);
  opacity: .8;
}
.iu-workspace input::placeholder,.iu-workspace textarea::placeholder {
  color: var(--iu-muted);
  opacity: .8;
}
.iu-header {
