.iu-header h1 {
  font-size: 19px;
  font-weight: 600;
  margin: 0;
  letter-spacing: -.5px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.iu-header h1 span {
  color: var(--iu-muted);
  padding: 3px 7px;
  font-size: 10px;
  font-weight: 400;
  border: 1px solid var(--iu-border);
  border-radius: 5px;
