  margin: 4px 0;
  padding: 15px 10px;
  line-height: 1.7;
  background: var(--studio-bg, #101012);
  border-radius: 9px;
}
.le-material-preview {
  display: block;
  width: 100%;
  aspect-ratio: 2;
  border-radius: 10px;
  background: #242426;
}
.le-preview-labels {
  display: flex;
  padding: 6px 0 12px;
  color: var(--studio-text-3, #888891);
  font-size: 10px;
  text-align: center;
}
.le-preview-labels>span {
  width: 50%;
}
.le-texture-row {
  display: flex;
  gap: 5px;
  margin-bottom: 14px;
}
.le-texture-row>button:first-child {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.le-color {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 17px;
}
.le-color>span:first-child {
  flex: 1;
}
.le-color>span:last-child {
  color: var(--studio-text-3, #888891);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}
.le-color input {
  width: 28px;
  height: 25px;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
}
.le-slider {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 14px 0;
}
.le-slider>span,.le-levels>span {
  width: 54px;
  flex-shrink: 0;
  font-size: 11px;
  color: var(--studio-text-2, #b4b4be);
}
.le-slider input {
  flex: 1;
  min-width: 0;
  height: 3px;
  accent-color: var(--studio-text-2, #b4b4be);
}
.le-slider output {
  width: 25px;
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: var(--studio-text-3, #888891);
  font-size: 10px;
}
.le-levels {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 13px;
}
.le-levels>div {
  display: flex;
  gap: 2px;
  flex: 1;
}
.le-levels button {
  flex: 1;
  padding: 5px 2px;
  font-size: 10px;
  border-color: transparent;
  background: transparent;
}
.le-levels button[aria-pressed=true] {
  background: var(--studio-surface-2, #313136);
  border-color: var(--studio-border, #ffffff20);
}
.le-replacement {
  position: relative;
}
.le-replacement>button:first-child {
  width: 100%;
  min-height: 140px;
  flex-direction: column;
  border-style: dashed;
  background: var(--studio-bg, #101012);
  color: var(--studio-text-2, #b4b4be);
}
.le-replacement img {
  max-height: 170px;
  width: 100%;
  -o-object-fit: contain;
  object-fit: contain;
  border-radius: 7px;
}
.le-replacement span {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.le-replacement>.le-icon {
  position: absolute;
  top: 7px;
  right: 7px;
  background: var(--studio-surface, #19191c);
}
.le-generate-panel {
  flex-shrink: 0;
  padding: 16px 18px;
  border-top: 1px solid var(--studio-border, #ffffff12);
  background: var(--studio-surface, #171719);
}
.le-workspace .le-primary {
  background: var(--studio-text-1, #eeeef0);
  color: var(--studio-bg, #151517);
  border-color: transparent;
}
.le-workspace .le-primary:hover:not(:disabled) {
  background: var(--studio-text-2, #c6c6ce);
}
.le-generate {
  width: 100%;
  min-height: 38px;
  margin-top: 13px;
  font-weight: 550 !important;
}
.le-cancel {
  width: 100%;
  margin-top: 7px;
}
.le-notice,.le-error {
  margin: 9px 0 0;
  font-size: 11px;
  line-height: 1.6;
  overflow-wrap: anywhere;
  color: var(--studio-text-2, #b4b4be);
}
.le-error {
  color: #bc826e;
}
.le-stage-error {
  position: absolute;
  top: 55px;
  left: 25px;
  right: 25px;
  z-index: 1;
  padding: 10px;
  border-radius: 8px;
  background: var(--studio-surface, #212125);
}
.le-picker {
  width: min(700px,90vw);
  max-height: 80vh;
  padding: 20px;
  margin: auto;
  background: var(--studio-surface, #19191c);
  color: var(--studio-text-1, #eeeef0);
  border: 1px solid var(--studio-border, #ffffff18);
  border-radius: 16px;
  box-shadow: 0 25px 80px #0005;
}
.le-picker::backdrop {
  background: #0007;
}
.le-picker>header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}
.le-picker-tools {
  display: flex;
  gap: 5px;
  margin-bottom: 14px;
}
.le-picker-tools button[aria-pressed=true] {
  background: var(--studio-surface-2, #303034);
}
.le-search {
  margin-bottom: 16px;
}
.le-picker-grid {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 10px;
}
.le-picker-grid button {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  min-width: 0;
  padding: 7px;
}
.le-picker-grid img,.le-picker-grid .sg-media {
  width: 100%;
  height: 112px;
  -o-object-fit: cover;
  object-fit: cover;
  border-radius: 6px;
}
.le-picker-grid span {
  width: 100%;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  font-size: 11px;
}
.le-picker-grid small,.le-picker-hint {
  color: var(--studio-text-3, #888891);
  font-size: 11px;
}
.le-picker-hint {
  text-align: center;
  padding: 14px;
}
@container (max-width: 1000px) {
  .le-subtitle {
    display: none;
  }
  .le-header {
    gap: 6px;
    padding: 10px 12px;
  }
  .le-sidebar {
    width: 310px;
  }
  .le-action-label {
    display: none;
  }
  .le-stage-hint {
    max-width: calc(100% - 30px);
    line-height: 1.7;
  }
}
@container (max-width: 700px) {
  .le-body {
    flex-direction: column;
    overflow: auto;
  }
  .le-stage {
    flex: none;
    min-height: 340px;
  }
  .le-sidebar {
    width: 100%;
    min-height: 450px;
    border-left: 0;
    border-top: 1px solid var(--studio-border, #ffffff12);
  }
  .le-panel-scroll {
    overflow: visible;
  }
  .le-header>.le-icon {
    display: none;
  }
  .le-header>.le-icon:first-child {
    display: inline-flex;
  }
  .le-view-tabs button {
    font-size: 10px;
    padding: 6px;
  }
  .le-picker-grid {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }
}
